#include <algorithm>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <numeric>
#include <vector>
#include <climits>
using namespace std;
struct Action{int A,B,dh2,c2,m;};
static Action mk(int A,int B){assert(0<=A&&A<=960&&0<=B&&B<=960);assert((9*A+11*B)%20==0&&(11*A+9*B)%20==0);return{A,B,(9*A+11*B)/20,(11*A+9*B)/20,max(A,B)};}
static vector<Action> fam655(){vector<Action>v;for(int i=0;i<=24;++i)for(int j=0;j<=24;++j)v.push_back(mk(40*i,40*j));const int ex[][2]={{6,236},{13,233},{67,237},{26,236},{94,234},{84,234},{3,223},{3,233},{74,234},{114,234},{4,234},{176,236},{115,235}};for(auto&p:ex)v.push_back(mk(4*p[0],4*p[1]));const int cut[][2]={{179,959},{613,953},{649,949},{539,959},{775,955},{885,945},{561,941},{419,959},{586,946},{215,955},{579,959},{70,910},{527,947},{497,957},{900,940},{291,951},{598,958}};for(auto&p:cut)v.push_back(mk(p[0],p[1]));assert(v.size()==655);for(auto&x:v)assert(!(x.dh2&1)&&!(x.c2&1));return v;}
static inline pair<long long,long long> br(const vector<long long>&p,const Action&x,int J,long long P,long long Q){long long H=9LL*x.A*Q-10LL*P*x.m;int h=J+x.dh2;if(h<(int)p.size())H+=p[h];int l=abs(J-x.c2);long long L=(J>=x.c2?-11LL*x.A*Q:9LL*x.B*Q-20LL*J*Q)-10LL*P*x.m+p[l];return{H,L};}
struct Run{int first,stable,last;long long firstroot,root,thr,checked;vector<long long>fixed,snap;};
static Run solve(const vector<Action>&a,long long P,long long Q,int snapH=-1,int M=6400,int Hmax=520){vector<long long>p(M+1),c(M+1),snap;long long thr=12480LL*Q+28800LL*P,fr=-1,checked=0;int first=-1,stable=-1;for(int h=1;h<=Hmax;++h){bool ch=false;for(int J=0;J<=M;++J){long long best=0;for(auto&x:a){auto z=br(p,x,J,P,Q);best=max(best,min(z.first,z.second));}c[J]=best;ch|=(c[J]!=p[J]);++checked;}p.swap(c);if(h==snapH)snap=p;if(first<0&&p[960]>=thr){first=h;fr=p[960];}if(!ch){stable=h;break;}}int last=-1;for(int J=0;J<=M;++J)if(p[J])last=J;return{first,stable,last,fr,p[960],thr,checked,p,snap};}
struct Aff{long long C,S;};static inline __int128 ev(const Aff&a,long long P,long long Q){return (__int128)a.C*Q+(__int128)a.S*P;}
static Aff symroot(const vector<Action>&a,long long P,long long Q,int M=6400,int Hmax=520){vector<Aff>p(M+1,{0,0}),c(M+1);for(int h=1;h<=Hmax;++h){bool ch=false;for(int J=0;J<=M;++J){Aff best{0,0};__int128 bv=0;for(auto&x:a){Aff H{9LL*x.A,-10LL*x.m};int jh=J+x.dh2;if(jh<=M){H.C+=p[jh].C;H.S+=p[jh].S;}int jl=abs(J-x.c2);Aff L{J>=x.c2?-11LL*x.A:9LL*x.B-20LL*J,-10LL*x.m};L.C+=p[jl].C;L.S+=p[jl].S;Aff mn=ev(H,P,Q)<=ev(L,P,Q)?H:L;auto mv=ev(mn,P,Q);if(mv>bv){bv=mv;best=mn;}}c[J]=best;ch|=c[J].C!=p[J].C||c[J].S!=p[J].S;}p.swap(c);if(!ch)return p[960];}assert(false);return{0,0};}
int main(){const int M=6400;auto old=fam655();long long P0=327,Q0=136730;auto r0=solve(old,P0,Q0,379,M);assert(r0.first==380&&r0.stable==444&&r0.firstroot==r0.thr&&r0.root==r0.thr);Action z=mk(597,957);assert(z.c2==759&&z.dh2==795);long long legal=0,best=LLONG_MIN,gap=0;int bu=-1,bv=-1,ba=-1,bb=-1;for(int U2=0;U2<=960;++U2)for(int V2=0;V2<=960;++V2){int na=11*U2-9*V2,nb=-9*U2+11*V2;if((na&1)||(nb&1))continue;int A=na/2,B=nb/2;if(A<0||A>960||B<0||B>960)continue;++legal;auto w=mk(A,B);auto q=br(r0.snap,w,960,P0,Q0);long long res=min(q.first,q.second)-r0.thr;if(res>best){best=res;gap=q.first-q.second;bu=U2;bv=V2;ba=A;bb=B;}}assert(legal==46177&&best==33500&&bu==759&&bv==795&&ba==597&&bb==957&&gap==6301700);auto aug=old;aug.push_back(z);auto ro=solve(aug,P0,Q0,-1,M);assert(ro.root-r0.root==33500);Aff f=symroot(aug,P0,Q0,M);assert(f.C==13063&&f.S==-214870);long long P=f.C-12480,Q=28800-f.S,g=std::gcd(llabs(P),llabs(Q));P/=g;Q/=g;assert(P==583&&Q==243670);auto rn=solve(aug,P,Q,-1,M);assert(rn.first==360&&rn.stable==455&&rn.last==5005&&rn.firstroot==rn.thr&&rn.root==rn.thr);int Cmax=0;for(auto&x:aug)Cmax=max(Cmax,x.c2);assert(Cmax<=960&&rn.last<M-Cmax);for(int J=M-Cmax;J<=M;++J)assert(rn.fixed[J]==0);long long un=9*Q-10*P,ud=10*Q;g=gcd(llabs(un),llabs(ud));un/=g;ud/=g;assert(un==21872&&ud==24367);long long wn=30*un-19*ud,wd=30*ud;g=gcd(llabs(wn),llabs(wd));wn/=g;wd/=g;assert(wn==193187&&wd==731010);long long in=12273*ud-un*13673,id=13673*ud;g=gcd(llabs(in),llabs(id));in/=g;id/=g;assert(in==335&&id==333169991);cout<<"I0130_B7_B18_B29_HALF_COSET_LIMIT_PASS\n";cout<<"old655_eps=327/136730 first="<<r0.first<<" stable="<<r0.stable<<"\n";cout<<"half_coset_vertices="<<legal<<" best=(597/960,957/960) quotient=(759/2,795/2) direct_root_residual_scaled="<<best<<" branch_gap_scaled="<<gap<<" oldeps_fixed_root_gain_scaled="<<(ro.root-r0.root)<<"\n";cout<<"new656_root_face=(13063-214870eps)/9600 critical_eps=583/243670 first="<<rn.first<<" stable="<<rn.stable<<" lastJ="<<rn.last<<"\n";cout<<"new_upper=21872/24367 new_width=193187/731010 improvement=335/333169991 total_goods_max="<<(rn.first+3)<<"\n";cout<<"tail_zero_buffer_Cmax="<<Cmax<<" MAXJ="<<M<<" outer_states="<<(r0.checked+ro.checked+rn.checked)<<"\n";}
